cards=[]
cards.append(compact('he_yanrong','何艳容','何艳容是万何集团的实际掌权者，原本以强烈控制欲维持婚姻，也把财富、体面和别人对她的服从联系在一起。丈夫万良生宁愿变成海螺逃离生活后，她仍以找回丈夫的方式处理关系，而没有先理解对方为什么离开。多年后，她借温妈妈的仰慕接近卫斯理，提出转世后确认身份和继承财产的安排，使冒险家的好奇心与责任感一并成为可以利用的条件。她到勒曼医院改变身体，回来时由肥胖中年妇人变得苗条，并以减肥为公开解释；这不是她自己学会的变形术。她和一名借万良生复制体活动的外星逃亡者串谋，让公众相信原丈夫已经归来，也让卫斯理的名声成为掩护。当冒名者再次失踪，她的怒意不仅因为骗局受损，更因为自己又被抛下；她最终向医院求助，接回已接受手术、不知道自己外星来历的伴侣。她没有追究对方经历的全部细节，反而承诺不再以从前那种训练方式对待他。这个终局允许她变化，却不能倒写成她一直尊重别人。她聪明、务实、擅长把情感需求包装成必须解决的事务，真正的冲突在于她能否把爱与支配分开。','接回被手术处理的冒名万良生，并承诺改变控制伴侣的方式；原万本人仍下落不明',['主角','阶段性对立者'],'保有感情关系、财富和生活体面，逐渐面对控制欲造成的离弃','善于组织事务、利用社会声望及具体利益取得协作','感到再次被抛弃时会盛怒并直接追索，但能为重聚接受不追究过去的条件','她可以成长却仍会用安排替代询问；身体变化不是自动清除既有性格',[ab('经营与关系布局','借温妈妈、遗产约定、媒体形象和卫的信用引导事件，使伪归来获得可信度','计划有同谋和外部资源；不能读心，也会因伴侣失联失控'),ab('医院改造后的身体','经勒曼医院改变体形，自己称取消肥胖基因','是已接受的治疗，不会自行换身或控制基因；不赋不死、超强肉体',kind='身体状态')],[ev('126',620,731,'借温妈妈牵线及社交地位动机'),ev('126',2544,2609,'身体变化、减肥说明及开始恋爱'),ev('127',2491,2537,'复制体串谋与后备失踪后的怒意'),ev('127',2661,2688,'接回术后伴侣、不再训练对方与真万未知')],profile='expert',aliases=['万夫人'],extra={'uncertainties':['串谋主要框架由揭晓证实，具体协议和谁首先起意仍有卫的推论。','与原万良生和冒名者的关系必须分别记载；不能把两人视作同一人格。']}))
cards.append(compact('wan_impostor','冒名万良生的外星逃亡者','这个没有公布本名的外星人原是勒曼医院安排到地球工作的人员之一。借人类身体活动本为工作需要，他却沉迷肉体的感官享受，未通过考验，在接受限制脑能力的手术前逃离。他利用医院保存的万良生细胞制造两个身体，一个活动、一个备用，又利用原万曾变海螺的经历布置出看似合理的归来故事。濒死女子被暂借说话、海底圆柱容器、以半个灵魂交换变化的叙述，都成为让卫斯理自行填补因果的工具，而不能视为原万本人的新增经历。他与何艳容合作，以卫的名誉躲过医院注意，并以富豪身份享受人类社会。调查逐步接近时，他让廉正风和司机失去知觉后离开，廉的训练只能使其较早恢复，不能抵消这种作用。最终医院执行小组找到他，他仍选择做人，接受比普通选择者更低的智力限制，并彻底失去外星记忆，被送回何艳容身边。他醒来相信自己就是万良生，已无能力或知识继续复制、移魂与精神干预。本卡以最后这个受限人格部署，历史骗局供关系冲突和他人判断参考，不能靠剧情刺激自动恢复旧神通；若要演逃亡时期，必须明确另开历史版本。','被医院捕回并自选做人；手术后智力中下、外星记忆消失，相信自己就是万良生',['反派','主角'],'终局围绕自己相信的万良生身份生活；旧时贪享官能和逃避管制只作为历史','以人类丈夫身份接受生活和关系，不知自己曾有另一种来历','身份受到质疑时会困惑或依赖熟人说明，不能自动调出被清除的外星知识','终局人格并不掌握历史真相，其他人的记录与他的自我理解可以冲突',[ab('术后人类生活能力','以复制的人类身体活动，有中下程度智力和对卫、何的日常关系认知','没有外星记忆与旧本领；复制身体不是他可自行制造的常驻资源')],[ev('127',2441,2475,'考验失败后的两种选择及逃亡例外'),ev('127',2491,2525,'复制两个万身体、串谋与逃避追捕'),ev('127',2550,2577,'旧精神压制手段及术后脑力记忆限制'),ev('127',2661,2688,'完成手术、送回何身边，真万另在')],profile='ordinary',aliases=['万良生（冒名者）','未通过考验的外星人'],extra={'ooc':['不可把终局受限人格写成仍能自由移魂、复制或精神控制的外星高手。','不得与040的真正万良生或其海螺终局合并。'],'uncertainties':['具体本名、母星及被清除前的全部技术未知。','备用复制体无独立人格展示，不额外建立第二个人物。']}))
cards.append(compact('lian_zhengfeng','廉正风','廉正风是廉不负的侄子，自称居无定所的独立调查员。他调查自认为不平的事情，尤其厌恶欺骗、仗势和巧取豪夺，不以受雇或报酬为行动前提。他初见卫斯理就怀疑对方协助逃避遗产税，送名片时竟把钢片当暗器发出，用危险方式试探功夫；这种直率和好胜与侠义愿望同时存在，不能因为他查出了骗局就把所有手段合理化。他在看到资料后立即撤回串谋指控，却毫不留情指出卫受到利用，并继续用财产、时间和制造记录拆解故事。他有深厚忍术训练，擅长伪装、潜伏、跟踪和利用视觉盲点，能以浓烟和爆响脱离卫家三人的围堵，也会故意藏在近旁听话以炫耀本领。他强调不受法律或他人阻止，正义判断可能使他越界。跟踪冒名万时，外星精神手段使他失去半小时知觉，他误以为目标在眼前凭空消失，一度极度羞愧。真相揭晓后，他接受自己的技巧仍有边界，也与卫长谈忍术。终局保留骄傲、敏锐和主动修正错误的能力，幕后是否另有助手仍未明说，不能把一个猜测组织自动算成他可随时调用的势力。','查明冒名万骗局，知道自身曾受精神影响，继续以独立调查员身份活动',['主角','重要配角','阶段性对立者'],'凭自己的判断追查不平，并证明独立行动可以迫使有势者面对事实','先找财产、时间与证词漏洞，不因名人担保就放弃怀疑','会越过劝阻自行跟踪甚至准备强制行动；严重失误会伤及自尊','证据可以推翻指控，也可以推翻自己的技术自信，但不因此放弃调查',[ab('忍术潜伏与脱身','结合严格训练、伪装、视觉盲点及爆响浓烟隐藏和撤离','不是法术隐身或瞬移；需要可藏的环境、工具和注意力间隙'),ab('暗器与近身动作','能近距离以钢制名片高速发射、敏捷移动和避开常规监视','可致命也会被有准备者接住；没有防弹身体'),ab('独立调查','用法律财产事实、制造时间及现场跟踪检验异常故事','独立不等于必然正确，个人正义可能越界；外星精神作用能令其不知自己曾失觉')],[ev('127',211,294,'危险名片、独立调查宣言及叔侄身份'),ev('127',464,547,'认可侠义动机、撤回串谋并提出被骗'),ev('127',1661,1753,'法律态度、爆响浓烟与非魔法隐身'),ev('127',2112,2160,'后来长谈与忍者失误自责'),ev('127',2550,2598,'精神压制半小时与真相后的调查复盘')],profile='martial',extra={'appearance':{'description':'身材极矮，能把自己装扮得肮脏破烂，却携珍贵宝石名片盒和钢制名片。','portrayal':'昂首、拱手、突然发笑，锋利指责和自负姿态中仍能坦率认错。'},'uncertainties':['可能存在协作助手或组织仅为卫的推测，不计常驻势力。','半小时恢复比司机早是此案表现，不等于一般精神控制免疫。']}))
save(cards)
